<section class="section-heading reveal"><div><h2>Выходные дни <?= $year ?></h2><p>Занятия на эти даты не создаются; график автоматически продолжается до нужного количества уроков.</p></div><a class="button button--secondary" href="<?= e(url('/calendar?month=' . $year . '-01')) ?>"><?= icon('calendar', 18) ?> Открыть календарь</a></section>
<section class="holiday-layout">
    <article class="panel reveal"><div class="panel__header"><div><p class="page-eyebrow">Новая дата</p><h3>Добавить выходной</h3></div></div><form method="post" action="<?= e(url('/education/holidays')) ?>" class="stacked-form"><?= csrf_field() ?><label class="field"><span class="field__label">Дата</span><span class="field__control"><input type="date" name="holiday_date" value="<?= e($year . '-01-01') ?>" required></span></label><label class="field"><span class="field__label">Название</span><span class="field__control"><input name="name" required maxlength="190" placeholder="Новый год"></span></label><button class="button button--primary" type="submit">Добавить и пересчитать расписания</button></form></article>
    <article class="panel reveal"><div class="panel__header"><div><p class="page-eyebrow">Календарный год</p><h3>Настроенные даты</h3></div><form method="get" action="<?= e(url('/education/holidays')) ?>"><select name="year" onchange="this.form.submit()"><?php for ($optionYear = (int) date('Y') - 1; $optionYear <= (int) date('Y') + 3; $optionYear++): ?><option value="<?= $optionYear ?>" <?= $optionYear === $year ? 'selected' : '' ?>><?= $optionYear ?></option><?php endfor; ?></select></form></div><div class="holiday-list"><?php foreach ($holidays as $holiday): ?><article><span class="holiday-list__date"><strong><?= e(format_date($holiday['holiday_date'], 'd')) ?></strong><small><?= e(format_date($holiday['holiday_date'], 'M')) ?></small></span><div><strong><?= e($holiday['name']) ?></strong><small><?= e(format_date($holiday['holiday_date'], 'l, d.m.Y')) ?></small></div><form method="post" action="<?= e(url('/education/holidays/' . $holiday['id'] . '/delete')) ?>"><?= csrf_field() ?><button class="table-action table-action--danger" type="submit" aria-label="Удалить"><?= icon('trash', 17) ?></button></form></article><?php endforeach; ?><?php if (!$holidays): ?><div class="empty-inline">На этот год выходные ещё не настроены.</div><?php endif; ?></div></article>
</section>
